374	    }
375	
376	    if (checkMode) {
377	      mislabelled.push(`${spec}: ${relPath}#L${hrefLine} -> label reads L${labelLine}`);
378	
379	      return whole;
380	    }
381	    relabelled += 1;
382	
383	    return `[L${hrefLine}](${relPath}#L${hrefLine})`;
384	  });
385	
386	  if (!checkMode && rewritten !== source) {
387	    writeFileSync(join(root, spec), rewritten);
388	  }
389	}
390	
391	const movedLabel = checkMode ? "stale" : "repointed";
392	const relabelledLabel = checkMode ? "mislabelled" : "relabelled";
393	const labelCount = checkMode ? mislabelled.length : relabelled;
394	
395	process.stdout.write(
396	  `${movedLabel}: ${moved}, up to date: ${upToDate}, unresolved: ${unresolved.length}, ${relabelledLabel}: ${labelCount}\n`
397	);
398	
399	if (retargeted > 0) {
400	  process.stdout.write(`retargeted (not checked): ${retargeted}\n`);
401	}
402	
403	if (checkMode) {
404	  for (const detail of staleDetails) {
405	    process.stderr.write(`stale ${detail}\n`);
406	  }
407	}
408	
409	for (const detail of unresolved) {
410	  process.stderr.write(`unresolved ${detail}\n`);
411	}
412	
413	for (const detail of rotten) {
414	  process.stderr.write(`rotten ${detail}\n`);
415	}
416	
417	for (const detail of mislabelled) {
418	  process.stderr.write(`mislabelled ${detail}\n`);
419	}
420	
421	const failed =
422	  rotten.length > 0 ||
423	  unresolved.length > 0 ||
424	  (checkMode && (moved > 0 || mislabelled.length > 0));
425	
426	process.exit(failed ? 1 : 0);
